<body>
${content}
</body>
</html>`;
}

function home(books) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || ''));

  const row = (b, showFinish) => `
    <div class="book-row">
      <span class="book-title"><a href="/book/${esc(b.id)}">${esc(b.title)}</a></span>
      <span class="book-author">by ${esc(b.author)}</span>
      <span class="book-actions">
        ${showFinish
          ? `<form method="post" action="/book/${esc(b.id)}/finish"><button class="secondary" type="submit">Mark finished</button></form>`
          : `<form method="post" action="/book/${esc(b.id)}/unfinish"><button class="secondary" type="submit">Mark reading</button></form>`
        }
      </span>
    </div>
  `;

  return layout('My Books', `
    <h1>My Books</h1>

    <form class="block" method="post" action="/add">
      <h2 style="margin-top:0;border:0;padding:0">Add a book</h2>
      <label for="title">Title</label>
      <input type="text" id="title" name="title" required autofocus>
      <label for="author">Author</label>
      <input type="text" id="author" name="author" required>
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" placeholder="Anything you want to remember..."></textarea>
      <button type="submit">Add to reading list</button>
    </form>

    <h2>Currently reading <span class="count">(${reading.length})</span></h2>
    ${reading.length === 0
      ? '<p class="empty">Nothing in progress yet. Add a book above to get started.</p>'
      : reading.map((b) => row(b, true)).join('')
    }

    <h2>Finished <span class="count">(${finished.length})</span></h2>
    ${finished.length === 0
      ? '<p class="empty">No finished books yet.</p>'
      : finished.map((b) => row(b, false)).join('')
    }
  `);
}

function bookDetail(book, host) {
  const statusLine = book.status === 'finished' && book.finishedAt
    ? `Finished on ${esc(new Date(book.finishedAt).toLocaleDateString())}`
    : 'Currently reading';

  const shareUrl = `${host}/book/${book.id}`;

  return layout(book.title, `
    <p><a class="back" href="/">&larr; All books</a></p>
    <h1>${esc(book.title)}</h1>
    <p class="meta">by ${esc(book.author)}</p>
    <p class="meta">${statusLine}</p>

    <h2>Notes</h2>
    ${book.notes
      ? `<div class="notes-box">${esc(book.notes)}</div>`
      : '<p class="empty">No notes yet.</p>'
    }

    <div style="margin-top:1.5rem">
      ${book.status === 'reading'
        ? `<form method="post" action="/book/${esc(book.id)}/finish" style="display:inline"><button type="submit">Mark as finished</button></form>`
        : `<form method="post" action="/book/${esc(book.id)}/unfinish" style="display:inline"><button class="secondary" type="submit">Move back to reading</button></form>`
      }
    </div>

    <h2>Share</h2>
    <p class="share-link"><a href="${esc(shareUrl)}">${esc(shareUrl)}</a></p>
  `);
}

function errorPage(msg) {
  return layout('Error', `<h1>${esc(msg)}</h1><p><a class="back" href="/">&larr; Back</a></p>`);
}

function readFormBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => {
      data += chunk;
      if (data.length > 1_000_000) {
        req.destroy(new Error('Payload too large'));
      }
    });
    req.on('end', () => {
      const out = {};
      new URLSearchParams(data).forEach((v, k) => { out[k] = v; });
      resolve(out);
    });
    req.on('error', reject);
  });
}

function send(res, code, body, contentType = 'text/html; charset=utf-8') {
  res.writeHead(code, { 'Content-Type': contentType });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(302, { Location: location });
  res.end();
}

const server = http.createServer(async (req, res) => {
  try {
    const host = req.headers.host || `localhost:${PORT}`;
    const url = new URL(req.url, `http://${host}`);
    const pathname = url.pathname;
    const method = req.method || 'GET';

    if (method === 'GET' && pathname === '/') {
      return send(res, 200, home(loadBooks()));
    }

    if (method === 'POST' && pathname === '/add') {
      const body = await readFormBody(req);
      const title = (body.title || '').trim();
      const author = (body.author || '').trim();
      const notes = (body.notes || '').trim();
      if (!title || !author) {
        return send(res, 400, errorPage('Title and author are both required.'));
      }
      const books = loadBooks();
      books.push({
        id: randomUUID(),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      });
      saveBooks(books);
      return redirect(res, '/');
    }

    const m = pathname.match(/^\/book\/([A-Za-z0-9-]+)(?:\/(finish|unfinish))?$/);
    if (m) {
      const id = m[1];
      const action = m[2];
      const books = loadBooks();
      const book = books.find((b) => b.id === id);
      if (!book) {
        return send(res, 404, errorPage('Book not found.'));
      }

      if (method === 'GET' && !action) {
        return send(res, 200, bookDetail(book, `http://${host}`));
      }

      if (method === 'POST' && action === 'finish') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
        saveBooks(books);
        return redirect(res, `/book/${id}`);
      }

      if (method === 'POST' && action === 'unfinish') {
        book.status = 'reading';
        book.finishedAt = null;
        saveBooks(books);
        return redirect(res, `/book/${id}`);
      }
    }

    return send(res, 404, errorPage('Page not found.'));
  } catch (err) {
    console.error(err);
    if (!res.headersSent) send(res, 500, errorPage('Something went wrong.'));
  }
});

server.listen(PORT, () => {
  console.log(`Books app running at http://localhost:${PORT}`);
});

